async () => {
const out={};
const form=document.querySelector('main form');
const radios=[...form.querySelectorAll('input[type=radio]')];
const colors=radios.filter(r=>/color/i.test(r.name));
const sizes=radios.filter(r=>/size/i.test(r.name));
for(const c of colors){ if(c.disabled){out[c.value]='disabled';continue;}
 c.click(); await new Promise(r=>setTimeout(r,200));
 out[c.value]=sizes.map(s=>s.value+(s.disabled?'(disabled)':'')).join(',') + ' | ' + form.innerText.replace(/\n+/g,' / ').slice(0,300);}
return {names:radios.map(r=>r.name+':'+r.value+':'+r.disabled),out};
}

