async () => {
const f=document.querySelector('main form'); const out={};
for(const c of ['blue','black']){
 f.querySelector(`input[value=${c}]`).click(); await new Promise(r=>setTimeout(r,200));
 f.querySelector('input[value=M]').click(); await new Promise(r=>setTimeout(r,200));
 const btn=[...f.querySelectorAll('button')].find(b=>/add to cart/i.test(b.innerText));
 out[c]={text:f.innerText.replace(/\n+/g,' / '),btnDisabled:btn.disabled,mChecked:f.querySelector('input[value=M]').checked};
}
return out;}

